-- | Animations: sequences of timed frames, each with a sprite reference and
-- its collision boxes. The equivalent of a MUGEN AIR action.
module Hugen.Anim
  ( AnimId,
    SpriteRef (..),
    Frame (..),
    Anim (..),
    frame,
    anim,
    looping,
    AnimPos (..),
    startAnim,
    advanceAnim,
    currentFrame,
    animTimeLeft,
  )
where

import Hugen.Box

-- | Animations are numbered, as in MUGEN.
type AnimId = Int

-- | What to draw. The core never looks inside: the shell maps it to a
-- sprite (MUGEN's group and image numbers) or, in the examples, to
-- rectangles generated by code.
data SpriteRef = SpriteRef !Int !Int
  deriving (Eq, Ord, Show)

data Frame = Frame
  { frameSprite :: !SpriteRef,
    -- | Ticks the frame is shown; @-1@ means forever.
    frameTime :: !Int,
    frameHurt :: ![Box],
    frameHit :: ![Box]
  }
  deriving (Eq, Show)

-- | A frame without hitboxes.
frame :: SpriteRef -> Int -> [Box] -> Frame
frame s t hurt = Frame s t hurt []

data Anim = Anim
  { animFrames :: ![Frame],
    -- | Index of the frame the animation loops back to.
    animLoopStart :: !Int
  }
  deriving (Eq, Show)

-- | An animation that loops from the start. Must have at least one frame.
anim :: [Frame] -> Anim
anim fs = Anim fs 0

-- | Loop back to the given frame instead of the first.
looping :: Int -> Anim -> Anim
looping n a = a {animLoopStart = n}

-- | Where a fighter is in its animation.
data AnimPos = AnimPos
  { apElem :: !Int,
    -- | Ticks spent in the current element.
    apElemTime :: !Int,
    -- | Ticks since the animation started (never resets on loop).
    apTime :: !Int
  }
  deriving (Eq, Show)

startAnim :: AnimPos
startAnim = AnimPos 0 0 0

-- | One tick forward.
advanceAnim :: Anim -> AnimPos -> AnimPos
advanceAnim a (AnimPos e et t)
  | dur >= 0 && et + 1 >= dur = AnimPos next 0 (t + 1)
  | otherwise = AnimPos e (et + 1) (t + 1)
  where
    fs = animFrames a
    dur = maybe (-1) frameTime (index fs e)
    next
      | e + 1 < length fs = e + 1
      | otherwise = min (animLoopStart a) (length fs - 1)

currentFrame :: Anim -> AnimPos -> Maybe Frame
currentFrame a p = index (animFrames a) (apElem p)

-- | MUGEN's AnimTime: ticks since the start minus the total duration of the
-- animation. Negative while it plays, 0 on the tick it ends. Animations with
-- an infinite frame never end and report -1.
animTimeLeft :: Anim -> AnimPos -> Int
animTimeLeft a p
  | any ((< 0) . frameTime) (animFrames a) = -1
  | otherwise = apTime p - sum (map frameTime (animFrames a))

index :: [x] -> Int -> Maybe x
index xs n
  | n < 0 = Nothing
  | otherwise = case drop n xs of
      (x : _) -> Just x
      [] -> Nothing
